export const ROUNDING_MODES = Object.freeze(['half-even', 'half-up', 'floor', 'ceil', 'trunc']);

function assertSafeInt(value, name) {
  if (!Number.isSafeInteger(value)) throw new RangeError(`${name} must be a safe integer`);
