export function divRound(n, d, mode = 'half-even') {
  assertSafeInt(n, 'n');
  assertSafeInt(d, 'd');
  if (d === 0) throw new RangeError('division by zero');
  if (!ROUNDING_MODES.includes(mode)) throw new RangeError(`unknown rounding mode: ${mode}`);
  if (d < 0) {
    n = -n;
    d = -d;
  }
  const r = n % d;
  const q = (n - r) / d;
  const sign = r > 0 ? 1 : r < 0 ? -1 : 0;
  const twice = Math.abs(2 * r);
  let out;
  switch (mode) {
    case 'floor':
      out = r < 0 ? q - 1 : q;
      break;
    case 'ceil':
      out = r > 0 ? q + 1 : q;
      break;
    case 'trunc':
      out = q;
      break;
    case 'half-up':
      out = twice >= d && r !== 0 ? q + sign : q;
      break;
    default:
      if (twice > d) out = q + sign;
      else if (twice === d && r !== 0 && q % 2 !== 0) out = q + sign;
      else out = q;
